// Scores candidate suppliers and returns a ranked recommendation.
// `query` matches the input schema: { suppliers: [...], quantity?: number, weights?: {...} }

const rowsIn = Array.isArray(query.suppliers) ? query.suppliers : [];
if (rowsIn.length === 0) {
  return 'No suppliers were passed in. Call find_suppliers first, then pass its rows into this tool as "suppliers".';
}

const w = Object.assign(
  { price: 0.4, lead_time: 0.25, rating: 0.2, reliability: 0.15 },
  query.weights || {}
);
const qty = Number(query.quantity) > 0 ? Number(query.quantity) : 1;

const num = (v, fallback) => {
  const n = Number(String(v === undefined || v === null ? '' : v).replace(/[^0-9.\-]/g, ''));
  return isFinite(n) ? n : fallback;
};

const rows = rowsIn.map((r) => ({
  name: r.name || r.supplier || r.supplier_name || 'Unknown supplier',
  country: r.country || '',
  unit_price: num(r.unit_price !== undefined ? r.unit_price : r.price, 0),
  lead_time_days: num(r.lead_time_days !== undefined ? r.lead_time_days : r.lead_time, 0),
  rating: num(r.rating, 0),
  on_time_rate: num(r.on_time_rate, 0),
  min_order_qty: num(r.min_order_qty, 0),
  contact: r.contact || r.email || ''
}));

const spans = {};
['unit_price', 'lead_time_days', 'rating', 'on_time_rate'].forEach((k) => {
  const vals = rows.map((r) => r[k]);
  spans[k] = { min: Math.min.apply(null, vals), max: Math.max.apply(null, vals) };
});

const norm = (val, key, higherIsBetter) => {
  const s = spans[key];
  if (s.max === s.min) return 1;
  const t = (val - s.min) / (s.max - s.min);
  return higherIsBetter ? t : 1 - t;
};

const scored = rows
  .map((r) => {
    const breakdown = {
      price: +(norm(r.unit_price, 'unit_price', false) * w.price).toFixed(4),
      lead_time: +(norm(r.lead_time_days, 'lead_time_days', false) * w.lead_time).toFixed(4),
      rating: +(norm(r.rating, 'rating', true) * w.rating).toFixed(4),
      reliability: +(norm(r.on_time_rate, 'on_time_rate', true) * w.reliability).toFixed(4)
    };
    const score = +Object.keys(breakdown)
      .reduce((a, k) => a + breakdown[k], 0)
      .toFixed(4);
    const flags = [];
    if (r.min_order_qty > qty) flags.push('minimum order qty ' + r.min_order_qty + ' is above the requested ' + qty);
    if (r.on_time_rate > 0 && r.on_time_rate < 0.9) flags.push('on-time delivery below 90%');
    return Object.assign({}, r, {
      extended_cost: +(r.unit_price * qty).toFixed(2),
      score: score,
      breakdown: breakdown,
      flags: flags
    });
  })
  .sort((a, b) => b.score - a.score);

const winner = scored[0];
const runnerUp = scored[1];

const why =
  winner.name + ' scores ' + winner.score + '/1.00 on the weighted model: ' +
  'unit price ' + winner.unit_price + ', lead time ' + winner.lead_time_days + ' days, ' +
  'rating ' + winner.rating + ', on-time rate ' + winner.on_time_rate + '. ' +
  'Extended cost for ' + qty + ' units is ' + winner.extended_cost + '.' +
  (runnerUp ? ' Closest alternative: ' + runnerUp.name + ' at ' + runnerUp.score + '.' : '') +
  (winner.flags.length ? ' Caveats: ' + winner.flags.join('; ') + '.' : '');

return JSON.stringify(
  { recommended: winner.name, contact: winner.contact, why: why, weights_used: w, quantity: qty, ranking: scored },
  null,
  2
);

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "suppliers": {
      "type": "array",
      "description": "Candidate suppliers to compare, normally the rows returned by find_suppliers.",
      "items": {
        "type": "object",
        "properties": {
          "name": { "type": "string" },
          "country": { "type": "string" },
          "unit_price": { "type": "number" },
          "lead_time_days": { "type": "number" },
          "rating": { "type": "number", "description": "0-5" },
          "on_time_rate": { "type": "number", "description": "0-1" },
          "min_order_qty": { "type": "number" },
          "contact": { "type": "string" }
        },
        "required": ["name", "unit_price", "lead_time_days"]
      }
    },
    "quantity": { "type": "number", "description": "Quantity from the RFQ. Used for extended cost and minimum-order checks." },
    "weights": {
      "type": "object",
      "description": "Optional scoring weights, should sum to 1. Defaults: price 0.4, lead_time 0.25, rating 0.2, reliability 0.15.",
      "properties": {
        "price": { "type": "number" },
        "lead_time": { "type": "number" },
        "rating": { "type": "number" },
        "reliability": { "type": "number" }
      }
    }
  },
  "required": ["suppliers"]
}
